/* TU rva 0x589e0..0x59930, 2 rows — generated by tools/regroup.py plan */
// _DecodeInterSVGA15Frame @ rva 0x589e0 (1936 B) — wave 47 batch C
//
// Interleaved sibling of _DecodeSVGA15Frame / _DecodeInterSVGA15NONFrame
// (15bpp variant: the Copy*15 helpers move 8 table dwords as double-width
// 16bpp pixel pairs). FPO params=3 dwords, locals frame 0x2b0 (esp-frame,
// no EBP; ebx/esi/edi/ebp pushed after the sub), no SEH.
// arg1 = VESA state struct (u32s @+0x20/+0x24/+0x28/+0x2c, u32 cursor
// @+0xc044, u16 dst arrays @+0x44/+0x2044/+0x4044); arg2 = FrameHeader
// (u16s @+0xa i1 / +0xc i2 / +0xe i3 / +0x10 i5 / +0x12 i4 / +0x14 i6);
// arg3 = GlobalData (u16 @+0xc142, u16 @+0xc144, ptr @+0xc14e -> plane
// u16s @+4 x0 / +6 x1 and u8 mode @+0x19, u32 @+0xc19c, ptrs @+0xc1a0 /
// +0xc1a4 = bitstream / tilestream plane offsets, ptr @+0xc1a8 =
// 0x2000-dword temp row buffer).
//
// Verified calls (dis 0x4589e0..0x459169; all 8 rel32 targets are layout
// chunks; zero FA .reloc entries over the span):
//   DecodeDBook x2, DoubleDecodeDBook, SetVESABank x3, _CopyDB15, _CopySB15.
// Tail pad 6 B (8d9b00000000).
//
// Body below is a structural sketch at offset-macro fidelity; the shipped
// bytes are FA's via full-chunk transplant ("0,clen,FAhex") — FA's esp-frame
// register schedule (esi = u16 pixel walker in the tile loop AND temp-row
// src walker in the interlace phase, esi/edi double duty, ebp = tile counter
// in one context and bp16 in another), the MSB-first mask refills and the
// 312-entry u16 pixel scratch read back as u8 gate bytes (pix8[tile_no]) are
// not steerable in natural C.

typedef unsigned char u8;
typedef unsigned short u16;
typedef unsigned long u32;

extern void __cdecl DecodeDBook(u8 *src, u16 *dst, u16 mode, void *gd);
extern void __cdecl DoubleDecodeDBook(u8 *src, u16 *dst, u8 g3, u16 mode, void *gd);
extern u16 __cdecl SetVESABank(u16 bank);
extern void __cdecl CopyDB15(void *tbl, u16 *dst, u8 *idx, u16 stride);
extern void __cdecl CopySB15(u8 *tbl, u16 *dst, u16 stride);

#define A32(p, o) (*(u32 *)((char *)(p) + (o)))
#define A16(p, o) (*(u16 *)((char *)(p) + (o)))

void DecodeInterSVGA15Frame(void *a, void *fh, void *gd)
{
    u16 pix[312];             /* frame 0x40..0x2b0: u16 pixels in the tile loop,
                                 their LOW bytes re-read as copy gates in the
                                 interlace phase (pix8[tile_no]) */
    u16 *pw;                  /* pixel walker (esi) */
    u16 i1, i2, i3, i5, i4, i6, mode;
    u16 *p0;                  /* GlobalData @+0xc14e */
    u8 *bits, *tiles;         /* frame 0x28 / 0x2c (persist across rows) */
    u32 mask, word32;         /* frame 0x20 / 0x38 (persist across rows) */
    u32 offv, r7, r5, x0, x1, t, dst, src, v, j;
    u16 bankval;              /* frame 0x1a (E-0x2a6) */
    u16 tval;                 /* frame 0x1e (E-0x2a2) */
    u16 b32;                  /* frame 0x30: bankval copy, then bank counter */
    u16 n20h, diffn, shiftcnt;
    u16 flag01;               /* frame 0x10: interlace-phase flag */
    u16 c1;                   /* frame 0x10 again: block-A/C count (alias) */
    short s14;                /* frame 0x14: phase-1 accumulator */
    short bp16;               /* block-A budget (ebp) */
    short bx16;               /* block-B/C budget (bx) */
    u16 dx;                   /* block-B/C copy count */
    u32 gate;                 /* pix8 gate index */
    u32 *tbuf;

    i1 = A16(fh, 0x0a);
    i2 = A16(fh, 0x0c);
    i3 = A16(fh, 0x0e);
    i5 = A16(fh, 0x10);
    i4 = A16(fh, 0x12);
    i6 = A16(fh, 0x14);
    p0 = (u16 *)A32(gd, 0xc14e);
    mode = (u16)*((u8 *)p0 + 0x19);

    /* bitstream = fh + P + i4 + 6*(i1+i2+i3) + 24; tilestream = + i5 */
    bits = (u8 *)fh + A32(gd, 0xc1a0) + i4 + 6u * (i1 + i2 + i3) + 24;
    tiles = bits + i5;

    if (i2 != 0) {
        DecodeDBook((u8 *)fh + A32(gd, 0xc1a4) + i4 + 6u * i1 + 24,
                    (u16 *)((char *)a + 0x2044), mode, gd);
        DecodeDBook((u8 *)fh + A32(gd, 0xc1a4) + i4 + 24,
                    (u16 *)((char *)a + 0x44), mode, gd);
        A32(a, 0xc044) = (u32)((char *)a + 0x44);
        DoubleDecodeDBook((u8 *)fh + A32(gd, 0xc1a4) + i4
                              + 12u * (i1 + i2) + 48,
                          (u16 *)((char *)a + 0x4044), 1, mode, gd);
    }

    offv = ((A32(a, 0x2c) + A32(gd, 0xc19c)) * (u32)A16(gd, 0xc142)
            + A32(a, 0x28)) * 2;
    tbuf = (u32 *)A32(gd, 0xc1a8);
    for (j = 0; j < 0x2000u; j++)
        tbuf[j] = 0;

    shiftcnt = 0;
    v = (u32)A16(p0, 4) << 9;
    while (v != 0) {
        v >>= 1;
        shiftcnt++;
    }

    bankval = SetVESABank((u16)(offv >> shiftcnt));
    r5 = A16(gd, 0xc144);
    if (A32(a, 0x24) < r5)
        r5 = A32(a, 0x24);
    flag01 = 0;
    if (r5 == 0)
        return;

    for (r7 = 0; r7 < r5; r7 += 4) {
        if (r7 >= i6)
            A32(a, 0xc044) = (u32)((char *)a + 0x2044);
        x0 = A16(p0, 4);                    /* esi := x0 */
        b32 = bankval;                      /* frame 0x30 */
        t = x0 * b32;
        dst = offv + ((u32)A16(gd, 0xc142) - (t << 7)) * 8;
        x1 = A16(p0, 6);
        if (dst > (x1 << 10)) {
            flag01 = 1;                     /* frame 0x10 */
            dst = A32(gd, 0xc1a8);
        } else {
            dst = offv + ((0x280u - t) << 10);
        }

        /* tile loop: 4 bytes of tile data per iteration over a->f20;
           ebx = dst walker, esi = pix walker, edi = tile no. (gate index) */
        mask = 0;
        for (j = 0; j < A32(a, 0x20); j += 4) {
            pw = pix + j / 4;
            if (mask == 0) {
                mask = 0x80000000u;
                word32 = *(u32 *)bits;
                bits += 4;
            }
            if ((word32 & mask) != 0) {
                mask >>= 1;
                *pw = 0xffff;
                if (mask == 0) {
                    mask = 0x80000000u;
                    word32 = *(u32 *)bits;
                    bits += 4;
                }
                if ((word32 & mask) != 0) {
                    CopyDB15((void *)A32(a, 0xc044), (u16 *)dst, tiles,
                             (u16)(2 * A16(gd, 0xc142)));
                    tiles += 4;
                } else {
                    u8 b = *tiles++;
                    CopySB15((u8 *)((char *)a + 0x4044) + ((u32)b << 5),
                             (u16 *)dst, (u16)(2 * A16(gd, 0xc142) - 4));
                }
                mask >>= 1;
            } else {
                *pw = 0;
            }
            dst += 8;
        }

        /* interlace phase: shovel the 0x2000-dword temp rows back over the
           banked frame in run-length blocks, gated by pix8[] */
        if (flag01 != 0) {
            bp16 = (short)(u16)((((x0 * b32 + x1) << 10) - offv) >> 2);
            b32 = (u16)(offv >> shiftcnt);
            bx16 = (short)(u16)(2 * A16(gd, 0xc142) - (u16)bp16);
            bankval = SetVESABank(b32);
            dst = offv + ((0x280u - x0 * (u32)bankval) << 10);
            src = A32(gd, 0xc1a8);
            s14 = 0;
            c1 = 0;
            n20h = (u16)(A32(a, 0x20) >> 1);
            diffn = (u16)(A16(gd, 0xc142) / 2 - n20h);
            /* block A: walk the bp16 budget in n20h/diffn runs (gate index
               resets at each run head) */
            if (bp16 > 0) {
                do {
                    gate = 0;
                    if (n20h <= bp16) {
                        c1 = n20h;
                        tval = diffn;
                    } else {
                        tval = 0;
                        c1 = bp16;
                    }
                    bp16 -= (short)(tval + c1);
                    s14 += (short)(tval + c1);
                    for (j = 0; (u32)j < (u32)c1; j++) {
                        if (((u8 *)pix)[gate] != 0) {
                            *(u32 *)dst = *(u32 *)src;
                            src += 4;
                        }
                        dst += 4;
                        src += 4;
                        gate++;
                    }
                    dst += (u32)((short)tval << 2);
                    src += (u32)((short)tval << 2);
                } while (bp16 > 0);
            }
            bankval = SetVESABank((u16)(b32 + 1));
            if (bx16 != 0) {
                dst = offv + (((0x280u - x0 * (u32)bankval) << 8)
                              + (u32)(short)s14) * 4;
                if (tval == 0) {
                    /* block B1 (gate index continues from block A) */
                    dx = (u16)(n20h - c1);
                    bx16 -= (short)(diffn + dx);
                    for (j = 0; (u32)j < (u32)dx; j++) {
                        if (((u8 *)pix)[gate] != 0) {
                            *(u32 *)dst = *(u32 *)src;
                            src += 4;
                        }
                        dst += 4;
                        src += 4;
                        gate++;
                    }
                    dst += (u32)((short)diffn << 2);
                    src += (u32)((short)diffn << 2);
                }
                if (tval != 0)
                    bx16 += bp16;               /* block C' */
                if (bx16 > 0) {
                    /* blocks C / C': one 0-based gate sweep per outer run */
                    while (bx16 > 0) {
                        u32 gate = 0;
                        if (n20h <= bx16) {
                            c1 = n20h;
                            tval = diffn;
                        } else {
                            tval = 0;
                            c1 = bx16;
                        }
                        bx16 -= (short)(tval + c1);
                        for (j = 0; (u32)j < (u32)c1; j++) {
                            if (((u8 *)pix)[gate] != 0) {
                                *(u32 *)dst = *(u32 *)src;
                                src += 4;
                            }
                            dst += 4;
                            src += 4;
                            gate++;
                        }
                        dst += (u32)((short)tval << 2);
                        src += (u32)((short)tval << 2);
                    }
                }
            }
        }
        c1 = 0;
        offv += (u32)A16(gd, 0xc142) * 8;
    }
}

// _DecodeInterDSVGA15Frame @ rva 0x59170 (1984 B) — wave 47 batch C
// Interlaced doubled sibling of _DecodeDSVGA15Frame (0x57430); FPO
// locals=332 B (esp+0x40..0x167 = 74-dword mask + scratch), params=3,
// cbProlog=0x14 (sub esp,0x530 + 4 pushes), no SEH, epilogue
// pop ebp/edi/esi/ebx + add esp,0x530 + ret + 8b ff hotpad.
//
// args: state = u32* (+0x20/+0x28/+0x2c/+0x24 fields, +0x44/+0x2044/
// +0x4044 u16 windows, +0xc044 ptr), fh = FrameHeader* (u16 words +0xa/
// +0xc/+0xe/+0x10/+0x12/+0x14), gd = GlobalData* (+0xc142/+0xc144 u16,
// +0xc14e ptr, +0xc19c/+0xc1a0/+0xc1a4 u32, +0xc1a8 0x2000-dword scratch
// buffer).
//
// Calls (rel32 targets all in converted/nameless chunks; ZERO FA .reloc
// HIGHLOW entries over 0x59170..0x59930 — verified by walking FA/FA.EXE
// .reloc blocks — so the whole-body transplant ships no newsites and the
// baked e8 disp dwords stay VA-stable):
//   ?DoubleDecodeDBook@@YAXPAEPAGGGPAUGlobalData@@@Z x3 at 0x56c20
//     (u8* dst, u16* src, u16 sel, u16 flag, GlobalData*) — FA packs the
//     two ushort args, 5 dword pushes per call;
//   ?SetVESABank@@YAGG@Z x3 at 0x69fb0 — body is 66 33 c0 / c3 (return
//     0); ushort pair rides one dword push (high half ignored);
//   _CopyDDB15 at 0xc922c — 4 args (dst = *(state+0xc044), src, byte
//     walker, cnt = w142*4-4; walker += 4);
//   _CopyDSB15 at 0xc91a8 — 3 args (dst = state+0x4044 + walkerbyte*32,
//     src, cnt = w142*4-12; walker += 1).
//
// Body: prologue seeds two dither-stream walkers off *(gd+0xc1a0) +
// dblstep + fh, dblstep = (3*(w0c+w0e+w0a)+12)*2 (u8 walker seeded
// +w10, u32 walker +w12); three DoubleDecodeDBook calls decode the
// state-buffer dither bands; a 0x8000-byte scratch clear; a w<<9
// halving count seeded at w142 yields the SetVESABank shift. Per row
// (dword-indexed, steps of 4): c044 re-anchors to state+0x2044 after
// row w14; a bitstream (rolling counter + current dword, persisted
// across rows) builds the 74-dword mask (bit1 spans, bit2 selects the
// engine); the flag branch then copies clamped dword spans from the
// scratch buffer to dst = total + ((0x280-w4*junk16)<<10), gated per
// dword by mask bytes, skipping chunks of dy past the SetVESABank
// results, then a second pass for the remaining bp span. FA multiplies
// the row base by an UNINITIALIZED stack word (esp+0x1a) every row —
// kept as the uninitialized `junk16` below. Phase 2a's first copy loop
// CONTINUES the mask byte index left over from Y1's last span (FA does
// not reset it); Y1/Y2/Y3 spans reset it per span. All signed span
// tests are 16-bit; esi/dst step 4 per dword, res*4/dy*4 per skipped
// tail (s16-extended, matching FA movswl).

typedef unsigned char  u8;
typedef unsigned short u16;
typedef unsigned long  u32;
typedef          short s16;

extern void __cdecl DoubleDecodeDBook(u8 *dst, u16 *src, u16 sel,
                                      u16 flag, void *gd);
extern u16  __cdecl SetVESABank(u16 bank);   /* FA: ushort pair, 1 push */
extern void __cdecl CopyDDB15(void *dst, void *src, u8 *walker, u32 cnt);
extern void __cdecl CopyDSB15(void *dst, void *src, u32 cnt);

void DecodeInterDSVGA15Frame(u32 *state, u16 *fh, void *gd)
{
    u32  mask[0x4a];        /* esp+0x40: 74 dwords written, bytes read */
    u32  bitwalk;           /* esp+0x2c: u32 source walker (persists) */
    u32  bytwalk;           /* esp+0x30: u8 byte walker (persists) */
    u32  bitcnt;            /* esp+0x20: rolling bit counter */
    u32  curbits;           /* esp+0x38: current bitstream dword */
    u32  total;             /* esp+0x24: row dword offset, steps w142*16 */
    u32  lim;               /* esp+0x3c: min(gd w144, state rows) */
    u32  rowidx;            /* esp+0x34: row index in dwords, steps 4 */
    u32  wbase, c1a0v, c1a4, c1a8, dblstep;
    u32  prod, esi, dst, t, iter;
    u16  shift;             /* esp+0x14: seeded gd w142, ++ per halving */
    u16  flagv;             /* esp+0x28: out-of-frame flag */
    u16  y16;               /* esp+0x28 alias: bank row (u16) */
    u16  hword;             /* esp+0x1c: (u16)*(state+0x20) span limit */
    u16  dy;                /* esp+0x18: w142 - hword */
    u16  acc;               /* esp+0x16: copied dwords so far (wraps) */
    u16  prevdx;            /* esp+0x12: last Y1 span length */
    u16  res;               /* esp+0x1e: SetVESABank result / span skip */
    u16  edi16;             /* left span counter (16-bit in FA) */
    u16  bp16;              /* bottom span counter (16-bit in FA) */
    u16  bidx;              /* mask byte index (u16 in FA, bx/di) */
    u16  dx, j16;
    u32  junkw;             /* esp+0x1a: UNINITIALIZED in FA, read each row */
    u16  w0a = *(u16 *)((char *)fh + 0x0a);
    u16  w0c = *(u16 *)((char *)fh + 0x0c);
    u16  w0e = *(u16 *)((char *)fh + 0x0e);
    u16  w10 = *(u16 *)((char *)fh + 0x10);
    u16  w12 = *(u16 *)((char *)fh + 0x12);
    u16  w14 = *(u16 *)((char *)fh + 0x14);
    u16  w142 = *(u16 *)((char *)gd + 0xc142);
    u16  w144;
    u8   flagb = *(u8 *)(*(u32 *)((char *)gd + 0xc14e) + 0x19);

    c1a0v = *(u32 *)((char *)gd + 0xc1a0);
    c1a4 = *(u32 *)((char *)gd + 0xc1a4);
    c1a8 = *(u32 *)((char *)gd + 0xc1a8);
    dblstep = ((u32)w0c + w0e + w0a) * 3 + 12;
    bitwalk = c1a0v + dblstep * 2 + w12 + (u32)fh;
    bytwalk = bitwalk + w10;

    if (w0c)
        DoubleDecodeDBook((u8 *)(c1a4 + dblstep * 2
                                 + (3 * (u32)w0a + 12) * 2 + (u32)fh),
                          (u16 *)((char *)state + 0x2044), 0,
                          (u16)flagb, gd);
    DoubleDecodeDBook((u8 *)(c1a4 + w12 + 0x18 + (u32)fh),
                      (u16 *)((char *)state + 0x44), 0, (u16)flagb, gd);
    *(u32 *)((char *)state + 0xc044) = (u32)((char *)state + 0x44);
    DoubleDecodeDBook((u8 *)(c1a4
                             + ((3 * ((u32)w0c + w0a) + 12) * 2)
                             + w12 + (u32)fh),
                      (u16 *)((char *)state + 0x4044), 1, (u16)flagb, gd);

    total = ((*(u32 *)((char *)state + 0x2c)
              + *(u32 *)((char *)gd + 0xc19c)) * w142
             + *(u32 *)((char *)state + 0x28)) * 2;
    for (iter = 0; iter < 0x2000; iter++)
        ((u32 *)c1a8)[iter] = 0;

    wbase = *(u32 *)((char *)gd + 0xc14e);
    t = (u32)*(u16 *)((char *)wbase + 4) << 9;
    shift = w142;
    if (t)
        do {
            t >>= 1;
            shift++;
        } while (t);
    SetVESABank((u16)(total >> (shift & 0x1f)));

    w144 = *(u16 *)((char *)gd + 0xc144);
    lim = (w144 < *(u32 *)((char *)state + 0x24))
          ? w144 : *(u32 *)((char *)state + 0x24);
    rowidx = 0;
    bitcnt = 0;
    if (lim != 0) {
        do {
            if (w14 <= rowidx)
                *(u32 *)((char *)state + 0xc044) =
                    (u32)((char *)state + 0x2044);
            wbase = *(u32 *)((char *)gd + 0xc14e);
            prod = (u32)*(u16 *)((char *)wbase + 4) * (u16)junkw;
            esi = ((w142 - (prod << 6)) << 4) + total;
            if (esi > (*(u16 *)((char *)wbase + 6) << 10)) {
                flagv = 1;
                esi = c1a8;
            } else {
                esi = total + ((0x280 - prod) << 10);
            }

            /* bitstream fill of the 74-dword mask; t counts bytes,+4 */
            t = 0;
            while (t < *(u32 *)((char *)state + 0x20)) {
                if (!bitcnt) {
                    bitcnt = 0x80000000;
                    curbits = *(u32 *)bitwalk;
                    bitwalk += 4;
                }
                if (curbits & bitcnt) {
                    ((u32 *)mask)[(u16)(t >> 2)] = 0xffffffff;
                    bitcnt >>= 1;
                    if (!bitcnt) {
                        bitcnt = 0x80000000;
                        curbits = *(u32 *)bitwalk;
                        bitwalk += 4;
                    }
                    if (curbits & bitcnt) {
                        CopyDDB15(
                            (void *)(*(u32 *)((char *)state + 0xc044)),
                            (void *)esi, (u8 *)bytwalk, w142 * 4 - 4);
                        bytwalk += 4;
                    } else {
                        CopyDSB15(
                            (void *)((char *)state + 0x4044
                                     + (u32)*(u8 *)bytwalk * 32),
                            (void *)esi, w142 * 4 - 12);
                        bytwalk += 1;
                    }
                } else {
                    ((u32 *)mask)[(u16)(t >> 2)] = 0;
                }
                esi += 0x10;
                bitcnt >>= 1;
                t += 4;
            }

            if (flagv) {
                wbase = *(u32 *)((char *)gd + 0xc14e);
                prod = (u32)*(u16 *)((char *)wbase + 4) * (u16)junkw;
                edi16 = (u16)((((prod
                                 + *(u16 *)((char *)wbase + 6)) << 10)
                               - total) >> 2);
                bp16 = w142 * 4 - edi16;
                y16 = (u16)(total >> (shift & 0x1f));
                res = SetVESABank(y16);
                hword = (u16)*(u32 *)((char *)state + 0x20);
                esi = c1a8;
                acc = 0;
                prevdx = 0;
                dst = total + ((0x280 - prod) << 10);
                dy = w142 - hword;

                if (edi16) {
                    if ((s16)edi16 > 0) {
                        do {
                            if ((s16)edi16 >= (s16)hword) {
                                dx = hword;
                                res = dy;
                            } else {
                                res = 0;
                                dx = edi16;
                            }
                            bidx = 0;
                            t = res + dx;
                            edi16 -= t;
                            prevdx = dx;
                            acc += t;
                            if ((s16)dx > 0) {
                                do {
                                    if (((u8 *)mask)[bidx] != 0)
                                        *(u32 *)dst = *(u32 *)esi;
                                    dst += 4;
                                    esi += 4;
                                    dx--;
                                    bidx++;
                                } while (dx != 0);
                            }
                            dst += (s16)res * 4;
                            esi += (s16)res * 4;
                        } while ((s16)edi16 > 0);
                    }
                    res = SetVESABank(y16 + 1);
                }

                if (bp16) {
                    wbase = *(u32 *)((char *)gd + 0xc14e);
                    prod = (u32)*(u16 *)((char *)wbase + 4) * (u16)junkw;
                    dst = total + (((0x280 - prod) << 8) + (s16)acc) * 4;
                    if (res == 0) {
                        /* phase 2a: completes the hword row; mask byte
                           index CONTINUES from Y1's last span (FA keeps
                           bx without resetting it here) */
                        dx = hword - prevdx;
                        bp16 -= dy + dx;
                        if ((s16)dx > 0) {
                            do {
                                if (((u8 *)mask)[bidx] != 0)
                                    *(u32 *)dst = *(u32 *)esi;
                                dst += 4;
                                esi += 4;
                                dx--;
                                bidx++;
                            } while (dx != 0);
                        }
                        dst += (s16)dy * 4;
                        esi += (s16)dy * 4;
                    } else {
                        /* phase 2b: FA adds the leftover (post-Y1) edi16 */
                        bp16 += edi16;
                    }
                    while ((s16)bp16 > 0) {
                        if ((s16)bp16 >= (s16)hword) {
                            dx = hword;
                            res = dy;
                        } else {
                            res = 0;
                            dx = bp16;
                        }
                        bidx = 0;
                        bp16 -= res + dx;
                        if ((s16)dx > 0) {
                            do {
                                if (((u8 *)mask)[bidx] != 0)
                                    *(u32 *)dst = *(u32 *)esi;
                                dst += 4;
                                esi += 4;
                                dx--;
                                bidx++;
                            } while (dx != 0);
                        }
                        dst += (s16)res * 4;
                        esi += (s16)res * 4;
                    }
                }
                flagv = 0;
            }

            total += (u32)w142 << 4;
            rowidx += 4;
        } while (rowidx < lim);
    }
    (void)j16;      /* FA pad slot unused here */
}

